CREATE TABLE `payroll_overtime` (
  `payroll_overtime_id` int NOT NULL AUTO_INCREMENT,
  `payroll_result_id` int NOT NULL,
  `overtime_request_id` int DEFAULT NULL,
  `hours_worked` decimal(10,2) NOT NULL,
  `hourly_rate` decimal(10,2) NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`payroll_overtime_id`),
  UNIQUE KEY `payroll_id_UNIQUE` (`payroll_result_id`),
  KEY `fk_payroll_overtime_request` (`overtime_request_id`),
  CONSTRAINT `fk_payroll_overtime_request` FOREIGN KEY (`overtime_request_id`) REFERENCES `overtime_request` (`overtime_request_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_payroll_overtime_result` FOREIGN KEY (`payroll_result_id`) REFERENCES `payroll_result` (`payroll_result_id`),
  CONSTRAINT `chk_payroll_overtime_amount` CHECK ((`amount` >= 0)),
  CONSTRAINT `chk_payroll_overtime_hours` CHECK ((`hours_worked` >= 0)),
  CONSTRAINT `chk_payroll_overtime_rate` CHECK ((`hourly_rate` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
