DROP TABLE IF EXISTS `withholding_tax_bracket`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `withholding_tax_bracket` (
  `tax_bracket_id` int NOT NULL AUTO_INCREMENT,
  `deduction_type_id` int NOT NULL,
  `min_salary` decimal(10,2) NOT NULL,
  `max_salary` decimal(10,2) NOT NULL,
  `base_tax` decimal(10,2) NOT NULL DEFAULT '0.00',
  `tax_rate` decimal(10,2) NOT NULL,
  `excess_over` decimal(10,2) NOT NULL,
  `effective_start_date` date NOT NULL,
  `effective_end_date` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`tax_bracket_id`),
  KEY `fk_tax_bracket_deduction_idx` (`deduction_type_id`),
  CONSTRAINT `fk_tax_bracket_deduction` FOREIGN KEY (`deduction_type_id`) REFERENCES `deduction_type` (`deduction_type_id`),
  CONSTRAINT `chk_withholding_base_tax` CHECK ((`base_tax` >= 0)),
  CONSTRAINT `chk_withholding_effective_dates` CHECK (((`effective_end_date` is null) or (`effective_end_date` >= `effective_start_date`))),
  CONSTRAINT `chk_withholding_excess_over` CHECK ((`excess_over` >= 0)),
  CONSTRAINT `chk_withholding_salary_range` CHECK ((`max_salary` >= `min_salary`)),
  CONSTRAINT `chk_withholding_tax_rate` CHECK ((`tax_rate` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb3;
